const axios = require('axios');
const fs = require('node:fs/promises');

const API = 'https://pasta.tldv.io/v1alpha1';
const headers = { 'x-api-key': '••••••', 'Content-Type': 'application/json' };
const filePath = './call.mp4';

async function upload() {
  const { size } = await fs.stat(filePath);

  // 1. Initiate: get the part plan and one signed URL per part
  const { data: plan } = await axios.post(`${API}/meetings/upload`, {
    name: 'Call with +1 555 010 0100',
    sizeBytes: size,
    contentType: 'video/mp4',
    phoneNumber: '+1 555 010 0100',
    metadata: { crmRecordId: 'rec_123' },
  }, { headers });

  // 2. PUT every part; the body must be exactly the part's byte range
  const file = await fs.open(filePath, 'r');
  try {
    for (const part of plan.parts) {
      const body = Buffer.alloc(part.size);
      await file.read(body, 0, part.size, part.byteRange.start);
      await axios.put(part.url, body, { headers: { 'Content-Type': 'application/octet-stream' }, maxBodyLength: Infinity });
    }
  } finally {
    await file.close();
  }

  // 3. Complete: tl;dv verifies the parts and queues the import
  const { data } = await axios.post(`${API}/meetings/upload/${plan.uploadId}/complete`, undefined, { headers });
  console.log(data.jobId);
}

upload().catch((error) => console.error(error.response?.data ?? error));
